/** @returns {string} SVG markup for the given icon. */
export function icon(name, { size = 24, cls = '', label = '', style = '' } = {}) {
  const d = PATHS[name] || PATHS.close;
  const a11y = label ? `role="img" aria-label="${label}"` : 'aria-hidden="true" focusable="false"';
  return `<svg class="ic ${cls}" width="${size}" height="${size}" viewBox="0 -960 960 960" fill="currentColor" ${a11y} ${style ? `style="${style}"` : ''}><path d="${d}"/></svg>`;
}

/** @returns {SVGSVGElement} */
export function iconEl(name, opts = {}) {
  const t = document.createElement('template');
  t.innerHTML = icon(name, opts).trim();
  return t.content.firstElementChild;
}

export function hasIcon(name) { return Object.hasOwn(PATHS, name); }
export function iconNames() { return Object.keys(PATHS); }

/**
 * Replaces every [data-icon] placeholder with an inline SVG.
 * Kept in this dependency-free module so both the app and the setup page
 * can hydrate icons without loading the rendering layer.
 */
export function hydrateIcons(root = document) {
  root.querySelectorAll('[data-icon]').forEach((el) => {
    if (el.dataset.iconDone === '1') return;
    const name = el.dataset.icon;
    const size = Number(el.dataset.iconSize || 0) || 24;
    el.innerHTML = icon(name, { size });
    el.dataset.iconDone = '1';
    el.style.display = 'inline-flex';
    el.style.lineHeight = '0';
  });
}
